; Emulator regression for staged w3d_clip_move_delta24.
;
; clip_vectors.bin begins with a uint32 count followed by 40-byte records
; generated by generate_clip_vectors.py.  gameplay_result.bin is a compact
; 32-byte mailbox decoded by run_gameplay_emulator_regression.py.

    assume adl=1
    org 0x040000
    jp start
    align 64
    db "MOS",0,1

mos_getkbmap:       equ 0x1e
mos_fopen:          equ 0x0a
mos_fclose:         equ 0x0b
mos_fread:          equ 0x1a
mos_fwrite:         equ 0x1b
fa_read:            equ 0x01
fa_write:           equ 0x02
fa_create_always:   equ 0x08

    macro MOSCALL function
        ld a,function
        rst.lil 08h
    endmacro

    include "wolf3d_sight.inc"
    include "wolf3d_fixture.inc"
    include "wolf3d_actors.inc"
    include "wolf3d_areas.inc"
    include "wolf3d_actor_sim.inc"
    include "wolf3d_motion.inc"

record_size:            equ 40
records_per_batch:      equ 512
rec_patch_kind:         equ 0       ; 0=tilemap byte, 1=static blocker bit
rec_patch_x:            equ 1
rec_patch_y:            equ 2
rec_patch_value:        equ 3
rec_door_action:        equ 4
rec_door_position:      equ 5
rec_expected_a:         equ 7
rec_pose_x:             equ 8
rec_pose_y:             equ 12
rec_dx:                 equ 16
rec_dy:                 equ 19
rec_expected_x:         equ 22
rec_expected_y:         equ 26
rec_expected_dirty:     equ 30
rec_sequence:           equ 32
rec_door_vertical:      equ 36      ; spare byte; patched door orientation

start:
    push af
    push bc
    push de
    push ix
    push iy
    call run_tests
    pop iy
    pop ix
    pop de
    pop bc
    pop af
    ld hl,0
    ret

run_tests:
    xor a
    ld hl,result_records
    ld (hl),a
    ld de,result_records+1
    ld bc,result_end-result_records-1
    ldir
    ld hl,0xffffff
    ld (result_first_index),hl
    ld (result_first_sequence),hl
    xor a
    ld (vector_handle),a
    ld (previous_patch_valid),a

    call initialize_test_world
    ld hl,vector_filename
    ld c,fa_read
    MOSCALL mos_fopen
    or a
    jp z,regression_fatal
    ld (vector_handle),a
    ld c,a
    ld hl,io_header
    ld de,4
    MOSCALL mos_fread
    ld hl,4
    or a
    sbc hl,de
    jp nz,regression_fatal
    ld a,(io_header+2)
    or a
    jp nz,regression_fatal
    ld a,(io_header+3)
    or a
    jp nz,regression_fatal
    ld hl,(io_header)
    ld (remaining),hl
    call read_batch

@loop:
    ld hl,(remaining)
    ld a,h
    or l
    jr z,@complete
    ld (record_ptr),iy
    call prepare_record
    lea hl,iy+rec_dx
    call w3d_clip_move_delta24
    ld (actual_a),a
    call validate_record

    ld hl,(result_records)
    inc.s hl
    ld (result_records),hl
    lea iy,iy+record_size
    ld hl,(remaining)
    dec.s hl
    ld (remaining),hl
    ld hl,(batch_remaining)
    dec.s hl
    ld (batch_remaining),hl
    ld a,h
    or l
    jr nz,@loop
    ld hl,(remaining)
    ld a,h
    or l
    jr z,@loop
    call read_batch
    jr @loop

@complete:
    call close_vector
    call restore_previous_patch
    call write_result
    call print_report
    ret

regression_fatal:
    call close_vector
    ld hl,0xffffff
    ld (result_errors),hl
    call write_result
    call print_report
    ret

initialize_test_world:
    xor a
    ld hl,test_tilemap
    ld (hl),a
    ld de,test_tilemap+1
    ld bc,W3D_MAP_BYTES-1
    ldir
    ld hl,test_tilemap
; ez80asm evaluates unparenthesized addition/multiplication left-to-right;
; use the literal row offset so this really initializes map row 63.
    ld iy,test_tilemap+4032
    ld b,64
@horizontal:
    ld (hl),1
    ld (iy+0),1
    inc hl
    inc iy
    djnz @horizontal
    ld ix,test_tilemap+64
    ld b,62
@vertical:
    ld (ix+0),1
    ld (ix+63),1
    lea ix,ix+64
    djnz @vertical

    ld hl,test_tilemap
    ld (w3d_map_ptr),hl
    xor a
    ld hl,test_static_bits
    ld (hl),a
    ld de,test_static_bits+1
    ld bc,511
    ldir
    ld hl,test_static_bits
    ld (w3d_static_blocking_ptr),hl
    xor a
    ld hl,w3d_actorat
    ld (hl),a
    ld de,w3d_actorat+1
    ld bc,W3D_MAP_BYTES-1
    ldir
    ld hl,w3d_doors
    ld (w3d_doors_ptr),hl
    xor a
    ld hl,w3d_doors
    ld (hl),a
    ld de,w3d_doors+1
    ld bc,W3D_FIXTURE_DOOR_COUNT*W3D_DOOR_SIZE-1
    ldir
    ret

prepare_record:
    call restore_previous_patch
    ld iy,(record_ptr)
    ld a,(iy+rec_patch_x)
    cp 0xff
    jr z,@no_patch
    ld b,a
    ld a,(iy+rec_patch_y)
    ld c,a
    ld a,b
    ld (previous_patch_x),a
    ld a,c
    ld (previous_patch_y),a
    ld a,(iy+rec_patch_kind)
    ld (previous_patch_kind),a
    or a
    jr nz,@static_patch
    call test_map_address
    ld a,(hl)
    ld (previous_patch_value),a
    ld a,(iy+rec_patch_value)
    ld (hl),a
    jr @remember_patch
@static_patch:
    call test_set_static_patch
@remember_patch:
    ld a,1
    ld (previous_patch_valid),a
@no_patch:
    ld a,(iy+rec_patch_x)
    ld (w3d_doors+W3D_DOOR_TILEX),a
    ld a,(iy+rec_patch_y)
    ld (w3d_doors+W3D_DOOR_TILEY),a
    ld a,(iy+rec_door_vertical)
    ld (w3d_doors+W3D_DOOR_VERTICAL),a
    xor a
    ld (w3d_doors+W3D_DOOR_LOCK),a
    ld a,(iy+rec_door_action)
    ld (w3d_doors+W3D_DOOR_ACTION),a
    ld a,(iy+rec_door_position+0)
    ld (w3d_doors+W3D_DOOR_POSITION+0),a
    ld a,(iy+rec_door_position+1)
    ld (w3d_doors+W3D_DOOR_POSITION+1),a

    ld hl,(iy+rec_pose_x)
    ld (w3d_player_pose+0),hl
    ld a,(iy+rec_pose_x+3)
    ld (w3d_player_pose+3),a
    ld hl,(iy+rec_pose_y)
    ld (w3d_player_pose+4),hl
    ld a,(iy+rec_pose_y+3)
    ld (w3d_player_pose+7),a
    xor a
    ld (w3d_player_dirty),a
    ld (w3d_world_dirty),a
    ret

validate_record:
    ld iy,(record_ptr)
    ld a,(actual_a)
    ld b,a
    ld a,(iy+rec_expected_a)
    cp b
    jr nz,@fail_a
    ld a,(w3d_player_dirty)
    ld b,a
    ld a,(iy+rec_expected_dirty)
    cp b
    jr nz,@fail_dirty
    ld ix,w3d_player_pose
    lea hl,iy+rec_expected_x
    ld b,8
@compare_pose:
    ld a,(hl)
    cp (ix+0)
    jr nz,@fail_pose
    inc hl
    inc ix
    djnz @compare_pose
    ret
@fail_a:
    ld a,1
    jr record_failure
@fail_dirty:
    ld a,2
    jr record_failure
@fail_pose:
    ld a,3

record_failure:
    ld (current_reason),a
    ld hl,(result_errors)
    inc.s hl
    ld (result_errors),hl
    ld hl,(result_first_index)
    ld de,0xffffff
    or a
    sbc hl,de
    ret nz
    ld hl,(result_records)
    ld (result_first_index),hl
    ld a,(current_reason)
    ld (result_first_reason),a
    ld a,(iy+rec_expected_a)
    ld (result_first_expected_a),a
    ld a,(actual_a)
    ld (result_first_actual_a),a
    ld hl,(iy+rec_sequence)
    ld (result_first_sequence),hl
    ld a,(iy+rec_sequence+3)
    ld (result_first_sequence+3),a
    ld hl,(w3d_player_pose)
    ld (result_first_actual_x),hl
    ld a,(w3d_player_pose+3)
    ld (result_first_actual_x+3),a
    ld hl,(w3d_player_pose+4)
    ld (result_first_actual_y),hl
    ld a,(w3d_player_pose+7)
    ld (result_first_actual_y+3),a
    ret

restore_previous_patch:
    ld a,(previous_patch_valid)
    or a
    ret z
    ld a,(previous_patch_x)
    ld b,a
    ld a,(previous_patch_y)
    ld c,a
    ld a,(previous_patch_kind)
    or a
    jr nz,@static_patch
    call test_map_address
    ld a,(previous_patch_value)
    ld (hl),a
    jr @done
@static_patch:
    call test_clear_static_patch
@done:
    xor a
    ld (previous_patch_valid),a
    ret

; B=x, C=y -> HL=&test_tilemap[y*64+x], preserving BC.
test_map_address:
    ld a,c
    ld e,a
    ld d,0
    inc de
    dec.s de
    sla e
    rl d
    sla e
    rl d
    sla e
    rl d
    sla e
    rl d
    sla e
    rl d
    sla e
    rl d
    ld a,e
    add a,b
    ld e,a
    jr nc,@ready
    inc d
@ready:
    ld hl,test_tilemap
    add hl,de
    ret

; B=x,C=y -> HL=&test_static_bits[(y*64+x)>>3], A=LSB-first mask.
test_static_bit_address:
    ld e,c
    ld d,0
    inc de
    dec.s de
    sla e
    rl d
    sla e
    rl d
    sla e
    rl d
    ld a,b
    srl a
    srl a
    srl a
    add a,e
    ld e,a
    jr nc,@byte_ready
    inc d
@byte_ready:
    ld hl,test_static_bits
    add hl,de
    push hl
    ld a,b
    and 7
    ld e,a
    ld d,0
    inc de
    dec.s de
    ld hl,w3d_static_bit_masks
    add hl,de
    ld a,(hl)
    pop hl
    ret

test_set_static_patch:
    call test_static_bit_address
    ld b,a
    ld a,(hl)
    or b
    ld (hl),a
    ret

test_clear_static_patch:
    call test_static_bit_address
    cpl
    and (hl)
    ld (hl),a
    ret

read_batch:
    ld hl,(remaining)
    ld de,records_per_batch
    or a
    sbc.s hl,de
    jr c,@remaining_smaller
    ld hl,records_per_batch
    jr @count_ready
@remaining_smaller:
    add.s hl,de
@count_ready:
    ld (batch_remaining),hl
    ld hl,(batch_remaining)
    add.s hl,hl
    add.s hl,hl
    add.s hl,hl
    push hl
    pop de
    add.s hl,hl
    add.s hl,hl
    add.s hl,de                    ; count * 40
    ex de,hl
    ld hl,record_buffer
    ld a,(vector_handle)
    ld c,a
    MOSCALL mos_fread
    ld hl,(batch_remaining)
    add.s hl,hl
    add.s hl,hl
    add.s hl,hl
    push hl
    pop bc
    add.s hl,hl
    add.s hl,hl
    add.s hl,bc
    or a
    sbc.s hl,de
    jp nz,fatal_short_read
    ld iy,record_buffer
    ret

fatal_short_read:
    jp regression_fatal

close_vector:
    ld a,(vector_handle)
    or a
    ret z
    ld c,a
    MOSCALL mos_fclose
    xor a
    ld (vector_handle),a
    ret

write_result:
    ld hl,result_filename
    ld c,fa_write | fa_create_always
    MOSCALL mos_fopen
    or a
    ret z
    ld (output_handle),a
    ld c,a
    ld hl,result_data
    ld de,result_end-result_data
    MOSCALL mos_fwrite
    ld a,(output_handle)
    ld c,a
    MOSCALL mos_fclose
    ret

print_report:
    ld hl,report_banner
    call print_string
    ld hl,(result_errors)
    ld a,h
    or l
    ld hl,report_pass
    jr z,@emit
    ld hl,report_fail
@emit:
    call print_string
    ret

print_string:
    push bc
    ld bc,0
    ld a,0
    rst.lil 18h
    pop bc
    ret

; Required by the included interactive module but not exercised here.
w3d_mark_render_submitted:
    ret
w3d_elapsed_ticks:
    dl 0
w3d_exit_requested:
    db 0

vector_filename:            asciz "clip_vectors.bin"
result_filename:            asciz "gameplay_result.bin"
report_banner:              asciz "\r\nWolf3D eZ80 gameplay regression: "
report_pass:                asciz "PASS\r\n"
report_fail:                asciz "FAIL\r\n"

vector_handle:              db 0
output_handle:              db 0
actual_a:                   db 0
current_reason:             db 0
previous_patch_valid:       db 0
previous_patch_kind:        db 0
previous_patch_x:           db 0
previous_patch_y:           db 0
previous_patch_value:       db 0
record_ptr:                 dl 0
remaining:                  dl 0
batch_remaining:            dl 0
io_header:                  dl 0
                            db 0

result_data:
    db "W3G1"
result_records:             dl 0
result_errors:              dl 0
result_first_index:         dl 0xffffff
result_first_reason:        db 0
result_first_expected_a:    db 0
result_first_actual_a:      db 0
result_first_sequence:      dl 0
                            db 0
result_first_actual_x:      dl 0
                            db 0
result_first_actual_y:      dl 0
                            db 0
                            db 0,0,0,0
result_end:

record_buffer:
    blkb records_per_batch*record_size,0
test_tilemap:
    blkb W3D_MAP_BYTES,0
test_static_bits:
    blkb 512,0
